fun guid(v:windows_sys.core.GUID):String = v.original.let { it.data1.toString(16).padStart(8,'0')+"|"+it.data2.toString(16).padStart(4,'0')+"|"+it.data3.toString(16).padStart(4,'0')+"|"+it.data4.joinToString("") { b -> b.toString(16).padStart(2,'0') } }
fun main() {
println("v0|"+V0.value.toBigEndianBytes().joinToString("") { it.toUByte().toString(16).padStart(2,'0') })
